package binding
import(
"net/http"
"reflect"
)
type headerBinding struct{}
(headerBinding)Name()string=>"header"
.Bind(req*http.Request,obj interface{})!{
mapHeader(obj req.Header)?
return validate(obj)
}
mapHeader(ptr interface{},h map[string][]string)! =>mappingByPtr(ptr headerSource(h),"header")
type headerSource map[string][]string
var _ setter=headerSource(nil)
(h headerSource)TrySet(value reflect.Value,field reflect.StructField,key string,opt setOptions)(isSetted bool,err error)=>setByForm(value field h http.CanonicalHeaderKey(key),opt)
